theory.configuration:
# AWS Route 53 using AWS CLI
aws route53 create-hosted-zone --name example.com --caller-reference 2024-03-15-1
aws route53 change-resource-record-sets --hosted-zone-id Z123456 --change-batch '{
  "Changes": [{
    "Action": "CREATE",
    "ResourceRecordSet": {
      "Name": "api.example.com",
      "Type": "A",
      "SetIdentifier": "prod-us-east",
      "Region": "us-east-1",
      "AliasTarget": {
        "HostedZoneId": "Z123",
        "DNSName": "alb-prod-123.us-east-1.elb.amazonaws.com",
        "EvaluateTargetHealth": true
      }
    }
  }]
}'

# AWS WAF using AWS CLI
aws wafv2 create-web-acl --name app-waf --scope CLOUDFRONT --default-action Allow --rules '
[{
  "Name": "AWS-AWSManagedRulesCommonRuleSet",
  "Priority": 1,
  "OverrideAction": {"None": {}},
  "Statement": {"ManagedRuleGroupStatement": {"VendorName": "AWS", "Name": "AWSManagedRulesCommonRuleSet"}},
  "VisibilityConfig": {"SampledRequestsEnabled": true}
},{
  "Name": "rate-limit-login",
  "Priority": 2,
  "Action": {"Block": {}},
  "Statement": {"RateBasedStatement": {"Limit": 100, "AggregateKeyType": "IP"}},
  "VisibilityConfig": {"SampledRequestsEnabled": true}
}]'

# AWS Security Group via Terraform
resource "aws_security_group" "web_sg" {
  name        = "web-sg"
  description = "Allow HTTP/S from anywhere"
  vpc_id      = aws_vpc.main.id
  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Azure Private Endpoint via Terraform
resource "azurerm_private_endpoint" "sql_pe" {
  name                = "sql-prod-pe"
  location            = azurerm_resource_group.main.location
  resource_group_name = azurerm_resource_group.main.name
  subnet_id           = azurerm_subnet.private_endpoints.id
  private_service_connection {
    name                           = "sql-connection"
    private_connection_resource_id = azurerm_mssql_server.sql.id
    subresource_names              = ["sqlServer"]
    is_manual_connection           = false
  }
  private_dns_zone_group {
    name                 = "sql-dns"
    private_dns_zone_ids = [azurerm_private_dns_zone.sql.id]
  }
}
